mapper.select:


    inner join sys_user u on u.user_name = tadvancedelivery.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tadvancedelivery.del_flag = '0'
    and tadvancedelivery.code like concat('%', #{code}, '%')
    and tadvancedelivery.origin_code like concat('%',
        #{originCode}, '%')

    and tadvancedelivery.origin_date = #{originDate}
    and tadvancedelivery.origin_data = #{originData}
    and tadvancedelivery.type = #{type}
    and tadvancedelivery.status = #{status}
    and tadvancedelivery.status in (${inStatus})
    and tadvancedelivery.auditor = #{auditor}
    and tadvancedelivery.new_local = #{newLocal}
     and tadvancedelivery.complete_state = #{completeState}
     and tadvancedelivery.quality_status = #{qualityStatus}
     and tadvancedelivery.put_status = #{putStatus}
     and tadvancedelivery.bom_id = #{bomId}


            and (tadvancedelivery.delivery_module = '2' or (tadvancedelivery.delivery_module = '0' and tadvancedelivery.status = '2'))
            and tadvancedelivery.delivery_module = #{deliveryModule}




${params.dataScope}
order by tadvancedelivery.create_time desc

select st.statisticsTime, ifnull(t1.inTaskCount,0) inTaskCount, ifnull(t2.outTaskCount,0) outTaskCount, ifnull(t3.moveTaskCount,0) moveTaskCount from (
select #{item} statisticsTime
) st left join (select count(1) inTaskCount, DATE_FORMAT(create_time, '%Y-%m') statisticsTime from t_advance_delivery where del_flag='0' and create_time>=#{beginDate} group by statisticsTime) t1 on st.statisticsTime=t1.statisticsTime left join (select count(1) outTaskCount, DATE_FORMAT(create_time, '%Y-%m') statisticsTime from t_out_delivery where del_flag='0' and create_time>=#{beginDate} group by statisticsTime) t2 on st.statisticsTime=t2.statisticsTime left join (select count(1) moveTaskCount, DATE_FORMAT(create_time, '%Y-%m') statisticsTime from t_task where del_flag='0' and task_type='5' and create_time>=#{beginDate} group by statisticsTime) t3 on st.statisticsTime=t3.statisticsTime
